1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      flex-direction: column;
21	      justify-content: center;
22	      align-items: center;
23	      gap: 20px;
24	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
25	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
26	      color: white;
27	      font-size: 14px;
28	      text-align: center;
29	    }
30	    .circle-container {
31	      cursor: pointer;
32	      transition: transform 0.3s ease;
33	      border: none;
34	      background: none;
35	      padding: 0;
36	    }
37	    .circle-container:hover,
38	    .circle-container:focus {
39	      transform: scale(1.08);
40	      outline: none;
41	    }
42	    .circle-container:focus-visible {
43	      outline: 3px solid rgba(255, 255, 255, 0.7);
44	      outline-offset: 12px;
45	      border-radius: 50%;
46	    }
47	    svg {
48	      width: min(400px, 80vw);
49	      height: min(400px, 80vw);
50	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
51	      display: block;
52	      transition: filter 0.3s ease;
53	    }
54	    circle {
55	      fill: #ffffff;
56	      stroke: rgba(255, 255, 255, 0.2);
57	      stroke-width: 2;
58	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease;
59	      animation: pulse 3s ease-in-out infinite;
60	    }
61	    .circle-container:hover circle,
62	    .circle-container:focus circle {
63	      fill: #e8f4f8;
64	      r: 205;
65	      stroke: rgba(255, 255, 255, 0.4);
66	    }
67	    .circle-container.active circle {
68	      fill: #ffd700;
69	      animation: pulse-active 0.6s ease-in-out;
70	      stroke: rgba(255, 215, 0, 0.3);
71	    }
72	    .circle-container.active:hover circle {
73	      fill: #ffed4e;
74	    }
75	    .circle-container.active svg {
76	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
77	    }
78	    .circle-container.color-mode-1 circle {
79	      fill: #ff6b9d;
80	    }
81	    .circle-container.color-mode-1.active svg {
82	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.5));
83	    }
84	    .circle-container.color-mode-2 circle {
85	      fill: #4ecdc4;
86	    }
87	    .circle-container.color-mode-2.active svg {
88	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.5));
89	    }
90	    .circle-container.color-mode-3 circle {
91	      fill: #95e1d3;
92	    }
93	    .circle-container.color-mode-3.active svg {
94	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.5));
95	    }
96	    .hint {
97	      font-size: 12px;
98	      opacity: 0.8;
99	      transition: opacity 0.3s ease;
100	    }
101	    .circle-container:hover ~ .hint,
102	    .circle-container:focus ~ .hint {
103	      opacity: 1;
104	    }
105	    @keyframes pulse {
106	      0%, 100% { r: 200; }
107	      50% { r: 202; }
108	    }
109	    @keyframes pulse-active {
110	      0% { r: 200; }
111	      50% { r: 210; }
112	      100% { r: 200; }
113	    }
114	    @keyframes fadeIn {
115	      from { opacity: 0; transform: scale(0.9); }
116	      to { opacity: 1; transform: scale(1); }
117	    }
118	    .circle-container svg {
119	      animation: fadeIn 0.6s ease-out;
120	    }
121	  </style>
122	</head>
123	<body>
124	  <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click to change color, press space or enter">
125	    <svg viewBox="0 0 400 400" role="presentation">
126	      <circle cx="200" cy="200" r="200"/>
127	    </svg>
128	  </button>
129	  <div class="hint" id="hint-text">Click to activate • Double-click for color</div>
130	
131	  <script>
132	    const circle = document.getElementById('decorative-circle');
133	    const hint = document.getElementById('hint-text');
134	    let colorMode = 0;
135	    let lastClickTime = 0;
136	
137	    circle.addEventListener('click', (e) => {
138	      const now = Date.now();
139	      const isDoubleClick = now - lastClickTime < 300;
140	      lastClickTime = now;
141	
142	      if (isDoubleClick) {
143	        e.preventDefault();
144	        cycleColor();
145	      } else {
146	        circle.classList.toggle('active');
147	        updateHint();
148	      }
149	    });
150	
151	    circle.addEventListener('dblclick', (e) => {
152	      e.preventDefault();
153	    });
154	
155	    circle.addEventListener('keydown', (e) => {
156	      if (e.key === ' ' || e.key === 'Enter') {
157	        e.preventDefault();
158	        circle.classList.toggle('active');
159	        updateHint();
160	      } else if (e.key === 'c' || e.key === 'C') {
161	        cycleColor();
162	      } else if (e.key === 'r' || e.key === 'R') {
163	        resetState();
164	      }
165	    });
166	
167	    function cycleColor() {
168	      circle.classList.remove('color-mode-1', 'color-mode-2', 'color-mode-3');
169	      colorMode = (colorMode + 1) % 4;
170	
171	      if (colorMode > 0) {
172	        circle.classList.add(`color-mode-${colorMode}`);
173	      }
174	
175	      circle.classList.add('active');
176	      updateHint();
177	    }
178	
179	    function resetState() {
180	      circle.classList.remove('active', 'color-mode-1', 'color-mode-2', 'color-mode-3');
181	      colorMode = 0;
182	      updateHint();
183	    }
184	
185	    function updateHint() {
186	      if (circle.classList.contains('active')) {
187	        hint.textContent = 'Active! • Press R to reset • Press C to change color';
188	      } else {
189	        hint.textContent = 'Click to activate • Double-click for color';
190	      }
191	    }
192	
193	    circle.addEventListener('mouseenter', () => {
194	      if (hint.textContent.includes('Click to activate')) {
195	        hint.textContent = 'Click to activate • Double-click for color • C: color • R: reset';
196	      }
197	    });
198	
199	    circle.addEventListener('mouseleave', () => {
200	      updateHint();
201	    });
202	
203	    circle.focus();
204	  </script>
205	</body>
206	</html>
